 ) x(s,t,p,qhash,whash) LOOP
  SELECT * INTO STRICT before_row FROM pg_policies WHERE schemaname=target.s AND tablename=target.t AND policyname=target.p;
  IF md5(coalesce(before_row.qual,''))<>target.qhash OR md5(coalesce(before_row.with_check,''))<>target.whash THEN RAISE EXCEPTION 'policy_drift: %.%/%',target.s,target.t,target.p;END IF;
  q:=pg_temp.fitpro_hoist_identity(before_row.qual);w:=pg_temp.fitpro_hoist_identity(before_row.with_check);
  IF q IS DISTINCT FROM before_row.qual THEN EXECUTE format('ALTER POLICY %I ON %I.%I USING(%s)',target.p,target.s,target.t,q);END IF;
  IF w IS DISTINCT FROM before_row.with_check THEN EXECUTE format('ALTER POLICY %I ON %I.%I WITH CHECK(%s)',target.p,target.s,target.t,w);END IF;
  SELECT * INTO STRICT after_row FROM pg_policies WHERE schemaname=target.s AND tablename=target.t AND policyname=target.p;
  IF (before_row.roles,before_row.cmd,before_row.permissive) IS DISTINCT FROM(after_row.roles,after_row.cmd,after_row.permissive) THEN RAISE EXCEPTION 'policy_scope_changed';END IF;
  changed:=changed+1;
 END LOOP;
 IF changed<>299 THEN RAISE EXCEPTION 'policy_count_mismatch';END IF;
END $migration$;
DROP FUNCTION pg_temp.fitpro_hoist_identity(text);
